import { createContext, useContext, useEffect, useState } from "react";

const CartContext = createContext(null);

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error("useCart must be used within CartProvider");
  }
  return context;
};

export const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState([]);

  useEffect(() => {
    try {
      const stored = localStorage.getItem("stride-cart");
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          setCartItems(parsed);
        }
      }
    } catch (error) {
      console.error("Failed to load cart from localStorage:", error);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem("stride-cart", JSON.stringify(cartItems));
    } catch (error) {
      console.error("Failed to save cart to localStorage:", error);
    }
  }, [cartItems]);

  const addItem = (product, quantity = 1, selectedSize, selectedColor) => {
    setCartItems((prev) => {
      const safePrev = Array.isArray(prev) ? prev : [];
      const existingIndex = safePrev.findIndex(
        (item) =>
          item.productId === product.id &&
          item.selectedSize === selectedSize &&
          item.selectedColor === selectedColor
      );

      if (existingIndex >= 0) {
        const updated = [...safePrev];
        updated[existingIndex] = {
          ...updated[existingIndex],
          quantity: updated[existingIndex].quantity + quantity
        };
        return updated;
      }

      return [
        ...safePrev,
        {
          id: `${product.id}-${Date.now()}`,
          productId: product.id,
          name: product.name,
          price: product.salePrice || product.price,
          image: product.images?.[0] || "",
          quantity,
          selectedSize,
          selectedColor
        }
      ];
    });
  };

  const removeItem = (itemId) => {
    setCartItems((prev) => {
      const safePrev = Array.isArray(prev) ? prev : [];
      return safePrev.filter((item) => item.id !== itemId);
    });
  };

  const updateQuantity = (itemId, quantity) => {
    setCartItems((prev) => {
      const safePrev = Array.isArray(prev) ? prev : [];
      if (quantity <= 0) {
        return safePrev.filter((item) => item.id !== itemId);
      }
      return safePrev.map((item) =>
        item.id === itemId ? { ...item, quantity } : item
      );
    });
  };

  const clearCart = () => {
    setCartItems([]);
  };

  const getCartTotal = () => {
    const safeItems = Array.isArray(cartItems) ? cartItems : [];
    return safeItems.reduce(
      (total, item) => total + (item.price || 0) * (item.quantity || 1),
      0
    );
  };

  const getCartCount = () => {
    const safeItems = Array.isArray(cartItems) ? cartItems : [];
    return safeItems.reduce(
      (count, item) => count + (item.quantity || 1),
      0
    );
  };

  const value = {
    cartItems,
    addItem,
    removeItem,
    updateQuantity,
    clearCart,
    getCartTotal,
    getCartCount
  };

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
};

export default CartContext;

const formatPrice = (price) => {
  const safePrice = typeof price === "number" ? price : 0;
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(safePrice);
};

export default formatPrice;

const getLocalStorage = (key, defaultValue = null) => {
  try {
    const item = localStorage.getItem(key);
    if (item === null) {
      return defaultValue;
    }
    return JSON.parse(item);
  } catch (error) {
    console.error(`Failed to get localStorage key "${key}":`, error);
    return defaultValue;
  }
};

const setLocalStorage = (key, value) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (error) {
    console.error(`Failed to set localStorage key "${key}":`, error);
    return false;
  }
};

const removeLocalStorage = (key) => {
  try {
    localStorage.removeItem(key);
    return true;
  } catch (error) {
    console.error(`Failed to remove localStorage key "${key}":`, error);
    return false;
  }
};

export { getLocalStorage, setLocalStorage, removeLocalStorage };
export default { getLocalStorage, setLocalStorage, removeLocalStorage };

import { Group, Text, rem } from "@mantine/core";
import { IconStar, IconStarHalf, IconStarFilled } from "@tabler/icons-react";

const RatingStars = ({ rating = 0, reviewCount = 0, size = 16 }) => {
  const safeRating = typeof rating === "number" ? rating : 0;
  const safeReviewCount = typeof reviewCount === "number" ? reviewCount : 0;

  const fullStars = Math.floor(safeRating);
  const hasHalfStar = safeRating % 1 >= 0.5;
  const emptyStars = 5 - fullStars - (hasHalfStar ? 1 : 0);

  return (
    <Group gap={4} align="center">
      <Group gap={2}>
        {[...Array(fullStars)].map((_, i) => (
          <IconStarFilled key={`full-${i}`} size={rem(size)} style={{ color: "#d4af37" }} />
        ))}
        {hasHalfStar && <IconStarHalf size={rem(size)} style={{ color: "#d4af37" }} />}
        {[...Array(emptyStars)].map((_, i) => (
          <IconStar key={`empty-${i}`} size={rem(size)} style={{ color: "#cbd5e1" }} />
        ))}
      </Group>
      {safeReviewCount > 0 && (
        <Text size="xs" c="dimmed">
          ({safeReviewCount})
        </Text>
      )}
    </Group>
  );
};

export default RatingStars;

import { Skeleton, SimpleGrid, Card, rem } from "@mantine/core";

const LoadingSkeleton = ({ count = 8, height = 350 }) => {
  const safeCount = typeof count === "number" ? count : 8;
  const safeHeight = typeof height === "number" ? height : 350;

  return (
    <SimpleGrid cols={{ base: 1, xs: 2, sm: 3, lg: 4 }} spacing="lg">
      {[...Array(safeCount)].map((_, index) => (
        <Card key={index} padding="md" radius="md" shadow="sm">
          <Skeleton height={rem(safeHeight * 0.7)} radius="md" mb="md" />
          <Skeleton height={16} width="80%" radius="sm" mb="xs" />
          <Skeleton height={14} width="60%" radius="sm" mb="md" />
          <Skeleton height={20} width="40%" radius="sm" />
        </Card>
      ))}
    </SimpleGrid>
  );
};

export default LoadingSkeleton;

import { Center, Stack, Text, Button, rem } from "@mantine/core";
import { IconSearch, IconShoppingCart, IconPackage } from "@tabler/icons-react";

const EmptyState = ({ 
  type = "search", 
  title = "No results found", 
  description = "Try adjusting your search or filter criteria",
  actionLabel = "Clear Filters",
  onAction 
}) => {
  const safeTitle = typeof title === "string" ? title : "No results found";
  const safeDescription = typeof description === "string" ? description : "";
  const safeActionLabel = typeof actionLabel === "string" ? actionLabel : null;

  const getIcon = () => {
    switch (type) {
      case "cart":
        return <IconShoppingCart size={rem(64)} stroke={1.5} />;
      case "products":
        return <IconPackage size={rem(64)} stroke={1.5} />;
      case "search":
      default:
        return <IconSearch size={rem(64)} stroke={1.5} />;
    }
  };

  return (
    <Center py={64}>
      <Stack align="center" gap="lg">
        {getIcon()}
        <Stack align="center" gap="xs">
          <Text size="xl" fw={600} c="dark">
            {safeTitle}
          </Text>
          {safeDescription && (
            <Text size="sm" c="dimmed" maw={400} ta="center">
              {safeDescription}
            </Text>
          )}
        </Stack>
        {safeActionLabel && onAction && (
          <Button variant="outline" onClick={onAction}>
            {safeActionLabel}
          </Button>
        )}
      </Stack>
    </Center>
  );
};

export default EmptyState;

import { Card, Image, Text, Group, Badge, Button, ActionIcon, Box, rem } from "@mantine/core";
import { IconHeart, IconEye, IconShoppingCart } from "@tabler/icons-react";
import { useDisclosure } from "@mantine/hooks";
import RatingStars from "./RatingStars";
import formatPrice from "../../lib/formatPrice";

const ProductCard = ({ product, onQuickView, onAddToCart }) => {
  const [hovered, { hover }] = useDisclosure(false);

  const safeProduct = product || {};
  const name = safeProduct.name || "Unnamed Product";
  const price = typeof safeProduct.price === "number" ? safeProduct.price : 0;
  const salePrice = typeof safeProduct.salePrice === "number" ? safeProduct.salePrice : null;
  const rating = typeof safeProduct.rating === "number" ? safeProduct.rating : 0;
  const reviewCount = typeof safeProduct.reviewCount === "number" ? safeProduct.reviewCount : 0;
  const category = safeProduct.category || "uncategorized";
  const image = safeProduct.images?.[0] || "";
  const inStock = safeProduct.inStock !== false;

  const displayPrice = salePrice || price;
  const hasDiscount = salePrice && salePrice < price;

  const handleAddToCart = () => {
    if (onAddToCart && inStock) {
      onAddToCart(safeProduct);
    }
  };

  const handleQuickView = () => {
    if (onQuickView) {
      onQuickView(safeProduct);
    }
  };

  return (
    <Card
      shadow="sm"
      padding="md"
      radius="md"
      style={{
        transition: "transform 150ms ease, box-shadow 150ms ease",
        transform: hovered ? "translateY(-4px)" : "none",
        ...(hovered && { boxShadow: "xl" })
      }}
      {...hover}
    >
      <Box pos="relative">
        <Image
          src={image}
          alt={name}
          height={200}
          fit="cover"
          radius="md"
          fallbackSrc="https://placehold.co/400x400?text=Product+Image"
        />
        {hasDiscount && (
          <Badge
            color="gold"
            variant="filled"
            pos="absolute"
            top={8}
            right={8}
            size="sm"
          >
            Sale
          </Badge>
        )}
        <Group pos="absolute" top={8} left={8} gap={4}>
          <ActionIcon
            variant="white"
            size="sm"
            radius="xl"
            aria-label="Add to wishlist"
            style={{ opacity: 0.9 }}
          >
            <IconHeart size={rem(16)} />
          </ActionIcon>
        </Group>
      </Box>

      <Group justify="space-between" mt="md" mb="xs">
        <Text fw={600} size="sm" lineClamp={1}>
          {name}
        </Text>
        <Badge variant="light" color="slate" size="xs">
          {category}
        </Badge>
      </Group>

      <Group gap="xs" mb="md">
        <RatingStars rating={rating} reviewCount={reviewCount} />
      </Group>

      <Group justify="space-between" align="center">
        <Group gap="xs">
          <Text fw={700} size="md">
            {formatPrice(displayPrice)}
          </Text>
          {hasDiscount && (
            <Text size="xs" c="dimmed" td="line-through">
              {formatPrice(price)}
            </Text>
          )}
        </Group>
        <Group gap={4}>
          <ActionIcon
            variant="subtle"
            size="sm"
            radius="xl"
            aria-label="Quick view"
            onClick={handleQuickView}
          >
            <IconEye size={rem(16)} />
          </ActionIcon>
          <ActionIcon
            variant="filled"
            size="sm"
            radius="xl"
            aria-label="Add to cart"
            onClick={handleAddToCart}
            disabled={!inStock}
          >
            <IconShoppingCart size={rem(16)} />
          </ActionIcon>
        </Group>
      </Group>
    </Card>
  );
};

export default ProductCard;

import { Box, Group, Text, ActionIcon, Burger, Drawer, ScrollArea, rem } from "@mantine/core";
import { useDisclosure, useMediaQuery } from "@mantine/hooks";
import { IconShoppingCart, IconMenu2, IconX } from "@tabler/icons-react";
import { useCart } from "../../context/CartContext";
import siteContent from "../../data/siteContent";

const Navbar = () => {
  const [opened, { open, close }] = useDisclosure(false);
  const isMobile = useMediaQuery("(max-width: 768px)");
  const { getCartCount } = useCart();

  const navigation = Array.isArray(siteContent.navigation) ? siteContent.navigation : [];
  const brandName = siteContent.brand?.name || "Stride";
  const cartCount = typeof getCartCount === "function" ? getCartCount() : 0;

  const scrollToSection = (href) => {
    close();
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
    }
  };

  const renderNavLinks = () => (
    <Group gap="xl" visibleFrom="md">
      {navigation.map((item, index) => (
        <Text
          key={index}
          component="a"
          href={item.href}
          onClick={(e) => {
            e.preventDefault();
            scrollToSection(item.href);
          }}
          style={{
            cursor: "pointer",
            textDecoration: "none",
            color: "var(--mantine-color-text)",
            fontWeight: 500,
            transition: "color 150ms ease"
          }}
          className="hover:text-slate-7"
        >
          {item.label}
        </Text>
      ))}
    </Group>
  );

  const renderMobileNav = () => (
    <Drawer
      opened={opened}
      onClose={close}
      title={brandName}
      padding="md"
      size="100%"
      hiddenFrom="md"
      closeButtonProps={{
        icon: <IconX size={rem(24)} />
      }}
    >
      <ScrollArea h="100%">
        <Group gap="md" direction="column" align="stretch">
          {navigation.map((item, index) => (
            <Text
              key={index}
              component="a"
              href={item.href}
              onClick={(e) => {
                e.preventDefault();
                scrollToSection(item.href);
              }}
              size="lg"
              style={{
                cursor: "pointer",
                textDecoration: "none",
                padding: rem(12),
                borderRadius: rem(8),
                "&:hover": {
                  backgroundColor: "var(--mantine-color-slate-0)"
                }
              }}
            >
              {item.label}
            </Text>
          ))}
        </Group>
      </ScrollArea>
    </Drawer>
  );

  return (
    <Box
      component="nav"
      style={{
        position: "sticky",
        top: 0,
        zIndex: 100,
        backgroundColor: "rgba(255, 255, 255, 0.95)",
        backdropFilter: "blur(8px)",
        borderBottom: "1px solid var(--mantine-color-slate-2)"
      }}
      h={64}
      px={{ base: "md", md: "xl" }}
    >
      <Group justify="space-between" h="100%" mx="auto" maw={1400}>
        <Group>
          <Burger
            opened={opened}
            onClick={open}
            hiddenFrom="md"
            size="sm"
            aria-label="Toggle navigation"
          />
          <Text
            component="a"
            href="#home"
            onClick={(e) => {
              e.preventDefault();
              scrollToSection("#home");
            }}
            size="xl"
            fw={700}
            style={{
              cursor: "pointer",
              textDecoration: "none",
              letterSpacing: rem(-0.5),
              color: "var(--mantine-color-slate-8)"
            }}
          >
            {brandName}
          </Text>
        </Group>

        {renderNavLinks()}

        <Group>
          <ActionIcon
            variant="subtle"
            size="lg"
            radius="xl"
            aria-label="Shopping cart"
            onClick={() => scrollToSection("#cart")}
            pos="relative"
          >
            <IconShoppingCart size={rem(22)} />
            {cartCount > 0 && (
              <Box
                style={{
                  position: "absolute",
                  top: 4,
                  right: 4,
                  width: rem(18),
                  height: rem(18),
                  borderRadius: "50%",
                  backgroundColor: "var(--mantine-color-gold-6)",
                  color: "white",
                  fontSize: rem(10),
                  fontWeight: 600,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center"
                }}
              >
                {cartCount > 99 ? "99+" : cartCount}
              </Box>
            )}
          </ActionIcon>
        </Group>
      </Group>

      {renderMobileNav()}
    </Box>
  );
};

export default Navbar;

