import { Group, UnstyledButton, Text, rem } from "@mantine/core";

const colorMap = {
  black: "#1e293b",
  white: "#ffffff",
  brown: "#92400e",
  tan: "#d6d3d1",
  navy: "#1e3a8a",
  blue: "#3b82f6",
  gray: "#6b7280",
  red: "#dc2626",
  green: "#16a34a",
  taupe: "#78716c",
  yellow: "#eab308"
};

const ColorSelector = ({ colors = [], selectedColor, onSelectColor }) => {
  const safeColors = Array.isArray(colors) ? colors : [];
  const safeSelectedColor = selectedColor !== undefined ? selectedColor : null;

  const handleColorSelect = (color) => {
    if (onSelectColor) {
      onSelectColor(color);
    }
  };

  const getColorStyle = (color) => {
    const baseColor = colorMap[color.toLowerCase()] || "#64748b";
    return {
      backgroundColor: baseColor,
      border: color.toLowerCase() === "white" 
        ? "2px solid var(--mantine-color-slate-3)" 
        : "2px solid transparent",
      outline: safeSelectedColor === color ? "2px solid var(--mantine-color-gold-6)" : "none",
      outlineOffset: safeSelectedColor === color ? "2px" : "0"
    };
  };

  return (
    <div>
      <Text size="sm" fw={500} mb="xs">
        Select Color
      </Text>
      <Group gap="xs" wrap="wrap">
        {safeColors.map((color, index) => (
          <UnstyledButton
            key={index}
            onClick={() => handleColorSelect(color)}
            aria-label={`Select ${color} color`}
            style={{
              width: rem(32),
              height: rem(32),
              borderRadius: "50%",
              ...getColorStyle(color),
              transition: "all 150ms ease",
              transform: safeSelectedColor === color ? "scale(1.1)" : "scale(1)"
            }}
          />
        ))}
      </Group>
    </div>
  );
};

export default ColorSelector;

import { Group, ActionIcon, Text, rem } from "@mantine/core";
import { IconMinus, IconPlus } from "@tabler/icons-react";

const QuantityControl = ({ quantity = 1, min = 1, max = 10, onChange }) => {
  const safeQuantity = typeof quantity === "number" ? quantity : 1;
  const safeMin = typeof min === "number" ? min : 1;
  const safeMax = typeof max === "number" ? max : 10;

  const handleDecrement = () => {
    if (safeQuantity > safeMin && onChange) {
      onChange(safeQuantity - 1);
    }
  };

  const handleIncrement = () => {
    if (safeQuantity < safeMax && onChange) {
      onChange(safeQuantity + 1);
    }
  };

  return (
    <Group gap={4} align="center">
      <ActionIcon
        variant="outline"
        size="sm"
        radius="sm"
        aria-label="Decrease quantity"
        onClick={handleDecrement}
        disabled={safeQuantity <= safeMin}
      >
        <IconMinus size={rem(16)} />
      </ActionIcon>
      <Text size="sm" fw={500} w={32} ta="center">
        {safeQuantity}
      </Text>
      <ActionIcon
        variant="outline"
        size="sm"
        radius="sm"
        aria-label="Increase quantity"
        onClick={handleIncrement}
        disabled={safeQuantity >= safeMax}
      >
        <IconPlus size={rem(16)} />
      </ActionIcon>
    </Group>
  );
};

export default QuantityControl;

