  const taxRate = 0.08;
  const tax = safeCartTotal * taxRate;
  const orderTotal = safeCartTotal + shippingCost + tax;

  return (
    <Paper padding="lg" radius="md" shadow="sm">
      <Stack gap="md">
        <Text size="lg" fw={600}>
          Order Summary
        </Text>

        <Group justify="space-between">
